/// <summary>
/// Extension of GUPPriceComponentCodeEntity
/// </summary>
[ExtensionOf(tableStr(GUPPriceComponentCodeEntity))]
internal final class METGUPPriceComponentCodeEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// Map entity to data source
    /// </summary>
    /// <param name = "_entityCtx">entity</param>
    /// <param name = "_dataSourceCtx">datasource</param>
    public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert || _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
        {
            if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceComponentCodeEntity, GUPPriceComponentCode)
                && this.METOnHold
                && this.PriceComponent != GUPPriceComponent::RetailDiscounts)
            {
                throw error("@GlobalUnifiedPricingMetcash:GUPPriceComponentCode_OnHold_Validation");
            }
        }

        next mapEntityToDataSource(_entityCtx, _dataSourceCtx);
    }
